def dependent_defined(facts):
    stated = facts.get('individual_is_dependent_of_taxpayer')
    if isinstance(stated, bool):
        return {'value': stated, 'used_units': ['u152_a_dep_pred'], 'open_dependencies': []}

    stated_child = facts.get('individual_is_qualifying_child_of_this_taxpayer')
    if stated_child is True:
        return {'value': True, 'used_units': ['u152_a_dep_pred', 'u152_c1_pred'], 'open_dependencies': []}

    used = ['u152_a_dep_pred']
    exclusion = married_dependent_exclusion_applies(facts)
    for unit in exclusion.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if exclusion.get('value') is True:
        return {'value': False, 'used_units': used, 'open_dependencies': []}

    child = qualifying_child(facts)
    for unit in child.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if child.get('value') is True:
        base = True
        base_open = []
    else:
        relative = qualifying_relative(facts)
        for unit in relative.get('used_units', []):
            if unit not in used:
                used.append(unit)
        if relative.get('value') is True:
            base = True
            base_open = []
        elif child.get('value') is False and relative.get('value') is False:
            base = False
            base_open = []
        else:
            base = None
            base_open = []
            for item in child.get('open_dependencies', []) + relative.get('open_dependencies', []):
                if item not in base_open:
                    base_open.append(item)

    if base is False:
        return {'value': False, 'used_units': used, 'open_dependencies': []}
    if base is True and exclusion.get('value') is False:
        return {'value': True, 'used_units': used, 'open_dependencies': []}
    open_dependencies = list(base_open)
    for item in exclusion.get('open_dependencies', []):
        if item not in open_dependencies:
            open_dependencies.append(item)
    return {'value': None, 'used_units': used, 'open_dependencies': open_dependencies}

