def taxpayer_and_spouse_exemption_applies(facts):
    role = facts.get('exemption_subject_role')
    if not isinstance(role, str):
        return {'value': None, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': ['exemption_subject_role is required']}
    role = role.strip().lower()
    individual = facts.get('taxpayer_is_individual')
    if individual is False:
        return {'value': False, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': []}
    if role == 'taxpayer':
        if individual is True:
            return {'value': True, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': []}
        return {'value': None, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': ['taxpayer_is_individual is required']}
    if role != 'spouse':
        return {'value': None, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': ['exemption_subject_role must be taxpayer or spouse']}

    has_spouse = facts.get('taxpayer_has_spouse')
    joint = facts.get('joint_return_made_by_taxpayer_and_spouse')
    gross_income = facts.get('spouse_gross_income_for_calendar_year')
    dependent_elsewhere = facts.get('spouse_is_dependent_of_another_taxpayer')
    conditions = (
        individual,
        has_spouse,
        None if not isinstance(joint, bool) else not joint,
        None if not isinstance(gross_income, (int, float)) or isinstance(gross_income, bool) else gross_income == 0,
        None if not isinstance(dependent_elsewhere, bool) else not dependent_elsewhere
    )
    if False in conditions:
        return {'value': False, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': []}
    missing = []
    names = ('taxpayer_is_individual', 'taxpayer_has_spouse', 'joint_return_made_by_taxpayer_and_spouse', 'spouse_gross_income_for_calendar_year', 'spouse_is_dependent_of_another_taxpayer')
    for index, value in enumerate(conditions):
        if value is None:
            missing.append(names[index] + ' is required')
    if missing:
        return {'value': None, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': missing}
    return {'value': True, 'used_units': ['u151_b_taxpayer_spouse_pred'], 'open_dependencies': []}

