def applicable_percentage(facts):
    used = ['u151_d3b_pct_qty']
    applies = exemption_phaseout_applies(facts)
    for unit in applies.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if applies.get('value') is False:
        return {'value': 0, 'used_units': used, 'open_dependencies': []}
    if applies.get('value') is None:
        return {'value': None, 'used_units': used, 'open_dependencies': applies.get('open_dependencies', [])}

    agi = facts.get('adjusted_gross_income')
    amount = facts.get('applicable_amount_under_section_68_b')
    if not isinstance(amount, (int, float)) or isinstance(amount, bool):
        amount_result = section68_applicable_amount(facts)
        amount = amount_result.get('value')
        for unit in amount_result.get('used_units', []):
            if unit not in used:
                used.append(unit)
        if amount is None:
            return {'value': None, 'used_units': used, 'open_dependencies': amount_result.get('open_dependencies', [])}

    separate_fact = facts.get('married_individual_filing_separate_return')
    if isinstance(separate_fact, bool):
        separate = separate_fact
    else:
        status = facts.get('filing_status')
        separate = None
        if isinstance(status, str):
            normalized = status.strip().lower().replace('-', '_').replace(' ', '_')
            if normalized in ('married_filing_separately', 'married_separate', 'mfs', 'separate_return'):
                separate = True
            elif normalized in ('joint', 'joint_return', 'married_filing_jointly', 'surviving_spouse', 'head_of_household', 'hoh', 'single', 'unmarried', 'not_married'):
                separate = False
        if separate is None:
            return {'value': None, 'used_units': used, 'open_dependencies': ['married-individual-filing-separate-return status is required to select the statutory increment']}

    step = 1250 if separate else 2500
    excess = agi - amount
    increments = int(excess // step)
    if excess % step != 0:
        increments += 1
    return {'value': min(100, 2 * increments), 'used_units': used, 'open_dependencies': []}

def exemption_amount(facts):
    used = ['u151_d1_amount_qty']
    special = special_year_exemption_rule_applies(facts)
    for unit in special.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if special.get('value') is True:
        if 'u151_d5_special_qty' not in used:
            used.append('u151_d5_special_qty')
        return {'value': 0, 'used_units': used, 'open_dependencies': []}

    disallowed = dependent_disallowance_applies(facts)
    for unit in disallowed.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if disallowed.get('value') is True:
        if 'u151_d2_disallow_qty' not in used:
            used.append('u151_d2_disallow_qty')
        return {'value': 0, 'used_units': used, 'open_dependencies': []}

    percentage = applicable_percentage(facts)
    for unit in percentage.get('used_units', []):
        if unit not in used:
            used.append(unit)
    if percentage.get('value') == 100:
        return {'value': 0, 'used_units': used, 'open_dependencies': []}
    if special.get('value') is False and disallowed.get('value') is False and isinstance(percentage.get('value'), (int, float)):
        return {'value': 2000 * (100 - percentage.get('value')) / 100, 'used_units': used, 'open_dependencies': []}

    open_dependencies = []
    for result in (special, disallowed, percentage):
        for item in result.get('open_dependencies', []):
            if item not in open_dependencies:
                open_dependencies.append(item)
    return {'value': None, 'used_units': used, 'open_dependencies': open_dependencies}

