def resolve_temporal_relation(direct_value, relation, query_year, event_date, activity_start, activity_end, status_start, status_end):
    if isinstance(direct_value, bool):
        return {'value': direct_value, 'open_dependencies': []}
    if relation == 'more_than_half_calendar_year':
        if not isinstance(query_year, int) or isinstance(query_year, bool):
            return {'value': None, 'open_dependencies': ['query_year is required for the calendar-year residence comparison']}
        if not isinstance(activity_start, str) or not isinstance(activity_end, str):
            return {'value': None, 'open_dependencies': ['the explicit start and end dates of the shared-principal-abode interval are required']}
        overlap = inclusive_year_overlap_days(activity_start, activity_end, query_year)
        return {'value': overlap * 2 > year_days(query_year), 'open_dependencies': []}
    if relation == 'event_in_either_two_preceding_calendar_years':
        if not isinstance(query_year, int) or isinstance(query_year, bool):
            return {'value': None, 'open_dependencies': ['query_year is required for the preceding-calendar-year comparison']}
        if not isinstance(event_date, str):
            return {'value': None, 'open_dependencies': ['the explicit event date is required']}
        event_year = calendar_year(event_date)
        return {'value': event_year == query_year - 1 or event_year == query_year - 2, 'open_dependencies': []}
    if relation == 'activity_entirely_during_status':
        values = (activity_start, activity_end, status_start, status_end)
        if not all(isinstance(value, str) for value in values):
            return {'value': None, 'open_dependencies': ['explicit activity and status start and end dates are required']}
        calendar_year(activity_start)
        calendar_year(activity_end)
        calendar_year(status_start)
        calendar_year(status_end)
        if activity_end < activity_start:
            raise ValueError('The observed activity interval ends before it begins')
        if status_end < status_start:
            raise ValueError('The observed status interval ends before it begins')
        return {'value': status_start <= activity_start and activity_end <= status_end, 'open_dependencies': []}
    raise ValueError('Unknown source-selected temporal relation')

